"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[5949],{9229(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/concepts/","label":"Course Overview","docId":"index","unlisted":false},{"type":"category","label":"Part I. Foundations","collapsible":false,"className":"sidebar-part","items":[{"type":"category","label":"1. Principles of Algorithmics","collapsed":true,"items":[{"type":"link","href":"/concepts/principles-of-algorithmics/algorithmic-thinking","label":"Algorithmic Thinking","docId":"principles-of-algorithmics/algorithmic-thinking","unlisted":false},{"type":"link","href":"/concepts/principles-of-algorithmics/case-study-pairwise","label":"Case Study: Maximum Pairwise Product","docId":"principles-of-algorithmics/case-study-pairwise","unlisted":false},{"type":"link","href":"/concepts/principles-of-algorithmics/data-structures","label":"Data Structures","docId":"principles-of-algorithmics/data-structures","unlisted":false},{"type":"link","href":"/concepts/principles-of-algorithmics/measuring-efficiency","label":"Measuring Efficiency","docId":"principles-of-algorithmics/measuring-efficiency","unlisted":false},{"type":"link","href":"/concepts/principles-of-algorithmics/complexity-analysis","label":"Complexity Analysis","docId":"principles-of-algorithmics/complexity-analysis","unlisted":false},{"type":"link","href":"/concepts/principles-of-algorithmics/asymptotic-notation","label":"Asymptotic Notation","docId":"principles-of-algorithmics/asymptotic-notation","unlisted":false},{"type":"link","href":"/concepts/principles-of-algorithmics/growth-rates","label":"Growth Rates and Predictions","docId":"principles-of-algorithmics/growth-rates","unlisted":false},{"type":"link","href":"/concepts/principles-of-algorithmics/complexity-of-loops","label":"Complexity of Loops","docId":"principles-of-algorithmics/complexity-of-loops","unlisted":false},{"type":"link","href":"/concepts/principles-of-algorithmics/searching-case-studies","label":"Case Studies: Searching","docId":"principles-of-algorithmics/searching-case-studies","unlisted":false},{"type":"link","href":"/concepts/principles-of-algorithmics/exercises","label":"Exercises","docId":"principles-of-algorithmics/exercises","unlisted":false},{"type":"link","href":"/concepts/principles-of-algorithmics/proofs","label":"Proofs","docId":"principles-of-algorithmics/proofs","unlisted":false},{"type":"link","href":"/concepts/principles-of-algorithmics/references","label":"References","docId":"principles-of-algorithmics/references","unlisted":false}],"collapsible":true,"href":"/concepts/principles-of-algorithmics"}],"collapsed":false},{"type":"category","label":"Part II. Problem Domains","collapsible":false,"className":"sidebar-part","items":[{"type":"category","label":"2. Sorting","collapsed":true,"items":[{"type":"link","href":"/concepts/sorting/the-sorting-problem","label":"The Sorting Problem","docId":"sorting/the-sorting-problem","unlisted":false},{"type":"link","href":"/concepts/sorting/bubble-sort","label":"Bubble Sort","docId":"sorting/bubble-sort","unlisted":false},{"type":"link","href":"/concepts/sorting/insertion-sort","label":"Insertion Sort","docId":"sorting/insertion-sort","unlisted":false},{"type":"link","href":"/concepts/sorting/selection-sort","label":"Selection Sort","docId":"sorting/selection-sort","unlisted":false},{"type":"link","href":"/concepts/sorting/quicksort","label":"Quicksort","docId":"sorting/quicksort","unlisted":false},{"type":"link","href":"/concepts/sorting/efficient-sorting","label":"Beyond Quadratic Sorting","docId":"sorting/efficient-sorting","unlisted":false},{"type":"link","href":"/concepts/sorting/comparing-sorting-algorithms","label":"Comparing Sorting Algorithms","docId":"sorting/comparing-sorting-algorithms","unlisted":false},{"type":"link","href":"/concepts/sorting/exercises","label":"Exercises","docId":"sorting/exercises","unlisted":false},{"type":"link","href":"/concepts/sorting/proofs","label":"Proofs","docId":"sorting/proofs","unlisted":false},{"type":"link","href":"/concepts/sorting/references","label":"References","docId":"sorting/references","unlisted":false}],"collapsible":true,"href":"/concepts/sorting"}],"collapsed":false},{"type":"category","label":"Part III. Design Techniques","collapsible":false,"className":"sidebar-part","items":[{"type":"category","label":"3. Brute Force","collapsed":true,"items":[{"type":"link","href":"/concepts/brute-force/brute-force-and-exhaustive-search","label":"Brute Force and Exhaustive Search","docId":"brute-force/brute-force-and-exhaustive-search","unlisted":false},{"type":"link","href":"/concepts/brute-force/exercises","label":"Exercises","docId":"brute-force/exercises","unlisted":false},{"type":"link","href":"/concepts/brute-force/references","label":"References","docId":"brute-force/references","unlisted":false}],"collapsible":true,"href":"/concepts/brute-force"},{"type":"category","label":"4. Divide and Conquer","collapsed":true,"items":[{"type":"link","href":"/concepts/divide-and-conquer/divide-and-conquer-scheme","label":"The Divide and Conquer Scheme","docId":"divide-and-conquer/divide-and-conquer-scheme","unlisted":false},{"type":"link","href":"/concepts/divide-and-conquer/analysis","label":"Analyzing Divide and Conquer","docId":"divide-and-conquer/analysis","unlisted":false},{"type":"link","href":"/concepts/divide-and-conquer/numbers-and-searches","label":"Numbers and Searches","docId":"divide-and-conquer/numbers-and-searches","unlisted":false},{"type":"link","href":"/concepts/divide-and-conquer/classic-problems","label":"Classic Problems","docId":"divide-and-conquer/classic-problems","unlisted":false},{"type":"link","href":"/concepts/divide-and-conquer/majority-mode-and-median","label":"Majority, Mode and Median","docId":"divide-and-conquer/majority-mode-and-median","unlisted":false},{"type":"link","href":"/concepts/divide-and-conquer/exercises","label":"Exercises","docId":"divide-and-conquer/exercises","unlisted":false},{"type":"link","href":"/concepts/divide-and-conquer/proofs","label":"Proofs","docId":"divide-and-conquer/proofs","unlisted":false},{"type":"link","href":"/concepts/divide-and-conquer/references","label":"References","docId":"divide-and-conquer/references","unlisted":false}],"collapsible":true,"href":"/concepts/divide-and-conquer"},{"type":"category","label":"5. Greedy Algorithms","collapsed":true,"items":[{"type":"link","href":"/concepts/greedy-algorithms/greedy-method","label":"The Greedy Method","docId":"greedy-algorithms/greedy-method","unlisted":false},{"type":"link","href":"/concepts/greedy-algorithms/classic-problems","label":"Classic Problems","docId":"greedy-algorithms/classic-problems","unlisted":false},{"type":"link","href":"/concepts/greedy-algorithms/exercises","label":"Exercises","docId":"greedy-algorithms/exercises","unlisted":false},{"type":"link","href":"/concepts/greedy-algorithms/proofs","label":"Proofs","docId":"greedy-algorithms/proofs","unlisted":false},{"type":"link","href":"/concepts/greedy-algorithms/references","label":"References","docId":"greedy-algorithms/references","unlisted":false}],"collapsible":true,"href":"/concepts/greedy-algorithms"},{"type":"category","label":"6. Dynamic Programming","collapsed":true,"items":[{"type":"link","href":"/concepts/dynamic-programming/dynamic-programming-method","label":"The Dynamic Programming Method","docId":"dynamic-programming/dynamic-programming-method","unlisted":false},{"type":"link","href":"/concepts/dynamic-programming/classic-problems","label":"Classic Problems","docId":"dynamic-programming/classic-problems","unlisted":false},{"type":"link","href":"/concepts/dynamic-programming/exercises","label":"Exercises","docId":"dynamic-programming/exercises","unlisted":false},{"type":"link","href":"/concepts/dynamic-programming/proofs","label":"Proofs","docId":"dynamic-programming/proofs","unlisted":false},{"type":"link","href":"/concepts/dynamic-programming/references","label":"References","docId":"dynamic-programming/references","unlisted":false}],"collapsible":true,"href":"/concepts/dynamic-programming"},{"type":"category","label":"7. Backtracking","collapsed":true,"items":[{"type":"link","href":"/concepts/backtracking/backtracking-scheme","label":"The Backtracking Scheme","docId":"backtracking/backtracking-scheme","unlisted":false},{"type":"link","href":"/concepts/backtracking/classic-problems","label":"Classic Problems","docId":"backtracking/classic-problems","unlisted":false},{"type":"link","href":"/concepts/backtracking/exercises","label":"Exercises","docId":"backtracking/exercises","unlisted":false},{"type":"link","href":"/concepts/backtracking/proofs","label":"Proofs","docId":"backtracking/proofs","unlisted":false},{"type":"link","href":"/concepts/backtracking/references","label":"References","docId":"backtracking/references","unlisted":false}],"collapsible":true,"href":"/concepts/backtracking"},{"type":"category","label":"8. Branch and Bound","collapsed":true,"items":[{"type":"link","href":"/concepts/branch-and-bound/branch-and-bound-scheme","label":"The Branch and Bound Scheme","docId":"branch-and-bound/branch-and-bound-scheme","unlisted":false},{"type":"link","href":"/concepts/branch-and-bound/classic-problems","label":"Classic Problems","docId":"branch-and-bound/classic-problems","unlisted":false},{"type":"link","href":"/concepts/branch-and-bound/exercises","label":"Exercises","docId":"branch-and-bound/exercises","unlisted":false},{"type":"link","href":"/concepts/branch-and-bound/proofs","label":"Proofs","docId":"branch-and-bound/proofs","unlisted":false},{"type":"link","href":"/concepts/branch-and-bound/references","label":"References","docId":"branch-and-bound/references","unlisted":false}],"collapsible":true,"href":"/concepts/branch-and-bound"}],"collapsed":false},{"type":"category","label":"Part IV. Execution Models","collapsible":false,"className":"sidebar-part","items":[{"type":"category","label":"9. Parallel Algorithms","collapsed":true,"items":[{"type":"link","href":"/concepts/parallel-algorithms/parallel-algorithms","label":"Concurrency and Parallelism","docId":"parallel-algorithms/parallel-algorithms","unlisted":false},{"type":"link","href":"/concepts/parallel-algorithms/fork-join-framework","label":"The Fork/Join Framework","docId":"parallel-algorithms/fork-join-framework","unlisted":false},{"type":"link","href":"/concepts/parallel-algorithms/parallel-performance","label":"Performance of Parallel Algorithms","docId":"parallel-algorithms/parallel-performance","unlisted":false},{"type":"link","href":"/concepts/parallel-algorithms/exercises","label":"Exercises","docId":"parallel-algorithms/exercises","unlisted":false},{"type":"link","href":"/concepts/parallel-algorithms/proofs","label":"Proofs","docId":"parallel-algorithms/proofs","unlisted":false},{"type":"link","href":"/concepts/parallel-algorithms/references","label":"References","docId":"parallel-algorithms/references","unlisted":false}],"collapsible":true,"href":"/concepts/parallel-algorithms"}],"collapsed":false},{"type":"category","label":"Appendices","collapsible":false,"className":"sidebar-part","items":[{"type":"category","label":"A. Mathematical Background","collapsed":true,"items":[{"type":"link","href":"/concepts/mathematical-background/sums-and-logarithms","label":"Sums, Logarithms and Factorials","docId":"mathematical-background/sums-and-logarithms","unlisted":false},{"type":"link","href":"/concepts/mathematical-background/induction-and-recurrences","label":"Induction, Correctness and Recurrences","docId":"mathematical-background/induction-and-recurrences","unlisted":false},{"type":"link","href":"/concepts/mathematical-background/exercises","label":"Exercises","docId":"mathematical-background/exercises","unlisted":false},{"type":"link","href":"/concepts/mathematical-background/references","label":"References","docId":"mathematical-background/references","unlisted":false}],"collapsible":true,"href":"/concepts/mathematical-background"},{"type":"link","href":"/concepts/glossary","label":"Glossary","docId":"glossary","unlisted":false}],"collapsed":false}]},"docs":{"backtracking/backtracking-scheme":{"id":"backtracking/backtracking-scheme","title":"The Backtracking Scheme","description":"Some problems resist every technique seen so far. There is no greedy criterion that guarantees the optimum, the problem does not split into independent halves, and there is no small table of subproblems to fill. Very often the only way to be sure of the answer is to examine the candidate solutions one by one. Backtracking is the paradigm that organizes that examination so that it is systematic (no candidate is forgotten) and as cheap as possible (whole families of candidates are discarded at once).","sidebar":"tutorialSidebar"},"backtracking/classic-problems":{"id":"backtracking/classic-problems","title":"Backtracking: Classic Problems","description":"This lesson applies the general schemes of backtracking to a series of classic problems. They are ordered from simple to more demanding, and each one illustrates a different aspect of the paradigm:","sidebar":"tutorialSidebar"},"backtracking/exercises":{"id":"backtracking/exercises","title":"Exercises: Backtracking","description":"These exercises review the two lessons on backtracking. They are different from the seminar activities (paths, Hamiltonian cycles and the traveling salesman) and from the lab problems, which are left for those sessions. Try each one before reading its solution: the solutions are grouped at the end of the page.","sidebar":"tutorialSidebar"},"backtracking/proofs":{"id":"backtracking/proofs","title":"Proofs: Backtracking","description":"Backtracking is an exact method: it promises to find every solution, or the best one. That promise depends on the pruning being safe, that is, never discarding a branch that contains what we are looking for. This page proves when that is the case.","sidebar":"tutorialSidebar"},"backtracking/references":{"id":"backtracking/references","title":"References: Backtracking","description":"Books, articles and resources to go deeper into the lessons of this chapter. The textbooks are listed in order of relevance to the course.","sidebar":"tutorialSidebar"},"branch-and-bound/branch-and-bound-scheme":{"id":"branch-and-bound/branch-and-bound-scheme","title":"The Branch and Bound Scheme","description":"Branch and bound (B&B) is the last design technique of the course. Like backtracking, it searches an implicit tree of states: nodes represent states of the problem, edges represent valid changes, and solving the problem means finding a node (or a path) in that tree. The difference is the order in which the tree is explored, and that single change makes it suitable for different problems.","sidebar":"tutorialSidebar"},"branch-and-bound/classic-problems":{"id":"branch-and-bound/classic-problems","title":"Branch and Bound: Classic Problems","description":"This lesson applies the general scheme of branch and bound to several problems. In each one, the work consists of answering the same three questions:","sidebar":"tutorialSidebar"},"branch-and-bound/exercises":{"id":"branch-and-bound/exercises","title":"Exercises: Branch and Bound","description":"These exercises review the two lessons on branch and bound. They are different from the seminar activities and from the lab problems, which are left for those sessions. Try each one before reading its solution: the solutions are grouped at the end of the page.","sidebar":"tutorialSidebar"},"branch-and-bound/proofs":{"id":"branch-and-bound/proofs","title":"Proofs: Branch and Bound","description":"Branch and bound finds the optimal solution only if its bounds and heuristics are valid. This page proves the facts used in the lessons: why the bounds of the examples are valid, why best-first branch and bound and A\\\\* stop at the optimum, and why the puzzle heuristics and the parity condition work. Safe pruning with a bound is proved in the backtracking chapter.","sidebar":"tutorialSidebar"},"branch-and-bound/references":{"id":"branch-and-bound/references","title":"References: Branch and Bound","description":"Books, articles and resources to go deeper into the lessons of this chapter. The textbooks are listed in order of relevance to the course.","sidebar":"tutorialSidebar"},"brute-force/brute-force-and-exhaustive-search":{"id":"brute-force/brute-force-and-exhaustive-search","title":"Brute Force and Exhaustive Search","description":"Brute force is the most direct way to design an algorithm: solve the problem by doing exactly what its statement says, with no attempt to exploit its structure. To find an element, look at every position. To find the best combination, generate every combination and keep the best one. To check whether a text contains a word, try the word at every position of the text.","sidebar":"tutorialSidebar"},"brute-force/exercises":{"id":"brute-force/exercises","title":"Exercises: Brute Force","description":"These exercises review the lesson on brute force and exhaustive search. Most of them ask the same two questions the solutions are grouped at the end of the page.","sidebar":"tutorialSidebar"},"brute-force/references":{"id":"brute-force/references","title":"References: Brute Force","description":"Books, articles and resources to go deeper into the lessons of this chapter. The textbooks are listed in order of relevance to the course.","sidebar":"tutorialSidebar"},"divide-and-conquer/analysis":{"id":"divide-and-conquer/analysis","title":"Analyzing Divide and Conquer","description":"The loops of iterative algorithms can be analyzed by counting iterations, as we did in the first chapter. Recursive algorithms need a different tool: the execution time is expressed in terms of itself applied to smaller sizes, giving a recurrence equation. Fortunately, most divide and conquer algorithms follow one of two very regular patterns, and for both of them the solution is known in general. This lesson presents those two patterns, explains where their formulas come from, and shows how to apply them.","sidebar":"tutorialSidebar"},"divide-and-conquer/classic-problems":{"id":"divide-and-conquer/classic-problems","title":"Divide and Conquer: Classic Problems","description":"This lesson presents some of the most famous divide and conquer algorithms. Two of them, Mergesort and Quicksort, we already know from the sorting chapter; now we can analyze them with the formulas of this chapter. The others (the Towers of Hanoi, the multiplication of large integers, the tennis tournament and the Tromino puzzle) show how the paradigm solves problems that would be hard to approach in any other way.","sidebar":"tutorialSidebar"},"divide-and-conquer/divide-and-conquer-scheme":{"id":"divide-and-conquer/divide-and-conquer-scheme","title":"The Divide and Conquer Scheme","description":"Divide and conquer is one of the oldest and most powerful strategies for designing algorithms. Instead of attacking a problem as a whole, it breaks it into smaller problems of the same kind, solves them (usually by applying the same strategy again), and combines their solutions. We have already met two examples: binary search, which discards half of the array at each step, and Quicksort, which partitions the array and sorts each part.","sidebar":"tutorialSidebar"},"divide-and-conquer/exercises":{"id":"divide-and-conquer/exercises","title":"Exercises: Divide and Conquer","description":"These exercises review the lessons of the chapter, from the divide and conquer scheme to majority, mode and median. Try each one before reading its solution: the solutions are grouped at the end of the page.","sidebar":"tutorialSidebar"},"divide-and-conquer/majority-mode-and-median":{"id":"divide-and-conquer/majority-mode-and-median","title":"Divide and Conquer: Majority, Mode and Median","description":"The last group of problems of this chapter comes from statistics this lesson develops the median completely, and leaves the divide and conquer versions of the majority element and the mode as challenges, with hints.","sidebar":"tutorialSidebar"},"divide-and-conquer/numbers-and-searches":{"id":"divide-and-conquer/numbers-and-searches","title":"Divide and Conquer: Numbers and Searches","description":"This lesson applies the paradigm and its analysis to a first set of classic problems: the factorial, sequential and binary search, the Fibonacci numbers and the greatest common divisor. Some of them show the strength of divide and conquer; others, especially Fibonacci, show what happens when it is applied badly. All of them are implemented, with tests, in the course repository.","sidebar":"tutorialSidebar"},"divide-and-conquer/proofs":{"id":"divide-and-conquer/proofs","title":"Proofs: Divide and Conquer","description":"This page proves the formulas used to analyze divide and conquer algorithms and the correctness and cost of several of them. The general techniques (induction, recursion trees, geometric series) are in the Mathematical Background appendix.","sidebar":"tutorialSidebar"},"divide-and-conquer/references":{"id":"divide-and-conquer/references","title":"References: Divide and Conquer","description":"Books, articles and resources to go deeper into the lessons of this chapter. The textbooks are listed in order of relevance to the course.","sidebar":"tutorialSidebar"},"dynamic-programming/classic-problems":{"id":"dynamic-programming/classic-problems","title":"Dynamic Programming: Classic Problems","description":"This lesson applies the design steps of dynamic programming to several classic problems: counting combinations, the 0/1 knapsack problem, the change with any coin system, the cheapest travel on a river, and two problems on strings, the longest common subsequence and the edit distance. The implementations of the course examples are in the course repository.","sidebar":"tutorialSidebar"},"dynamic-programming/dynamic-programming-method":{"id":"dynamic-programming/dynamic-programming-method","title":"The Dynamic Programming Method","description":"Divide and conquer breaks a problem into subproblems and combines their solutions. It works beautifully when the subproblems are independent. But we saw in the divide and conquer chapter that the naive recursive Fibonacci solves the same subproblems again and again, and becomes exponential. Dynamic programming keeps the idea of solving a problem through its subproblems, but solves each subproblem only once, storing its solution in a table for later use.","sidebar":"tutorialSidebar"},"dynamic-programming/exercises":{"id":"dynamic-programming/exercises","title":"Exercises: Dynamic Programming","description":"These exercises review the two lessons on dynamic programming. For each problem, follow the design steps of the first lesson the solutions are grouped at the end of the page.","sidebar":"tutorialSidebar"},"dynamic-programming/proofs":{"id":"dynamic-programming/proofs","title":"Proofs: Dynamic Programming","description":"A dynamic programming algorithm is correct if its recurrence is correct: the optimal value of each subproblem must be obtained from the optimal values of smaller subproblems. This page proves the recurrences used in the lessons.","sidebar":"tutorialSidebar"},"dynamic-programming/references":{"id":"dynamic-programming/references","title":"References: Dynamic Programming","description":"Books, articles and resources to go deeper into the lessons of this chapter. The textbooks are listed in order of relevance to the course.","sidebar":"tutorialSidebar"},"glossary":{"id":"glossary","title":"Glossary","description":"The main terms of the course, in alphabetical order. Each entry gives a short definition and links to the lesson where the term is explained in detail.","sidebar":"tutorialSidebar"},"greedy-algorithms/classic-problems":{"id":"greedy-algorithms/classic-problems","title":"Greedy Algorithms: Classic Problems","description":"This lesson applies the greedy strategy to a series of classic problems. For some of them, a good heuristic gives the optimal solution, and we will see why. For others, it gives only a good solution, and a counterexample shows it. Learning to tell both situations apart is the main goal. The implementations are in the course repository.","sidebar":"tutorialSidebar"},"greedy-algorithms/exercises":{"id":"greedy-algorithms/exercises","title":"Exercises: Greedy Algorithms","description":"These exercises review the two lessons on greedy algorithms. Most of them follow the same pattern the solutions are grouped at the end of the page.","sidebar":"tutorialSidebar"},"greedy-algorithms/greedy-method":{"id":"greedy-algorithms/greedy-method","title":"The Greedy Method","description":"Many problems ask not just for a solution, but for the best one they build the solution step by step and, at each step, they take the choice that looks best right now, without ever reconsidering it.","sidebar":"tutorialSidebar"},"greedy-algorithms/proofs":{"id":"greedy-algorithms/proofs","title":"Proofs: Greedy Algorithms","description":"A greedy algorithm is only useful if we can prove that its choices lead to an optimal solution. This page proves the optimality of the greedy algorithms that the lessons call optimal, mostly with exchange arguments: take any optimal solution and show that it can be changed, step by step, into the greedy one without getting worse.","sidebar":"tutorialSidebar"},"greedy-algorithms/references":{"id":"greedy-algorithms/references","title":"References: Greedy Algorithms","description":"Books, articles and resources to go deeper into the lessons of this chapter. The textbooks are listed in order of relevance to the course.","sidebar":"tutorialSidebar"},"index":{"id":"index","title":"Course Overview","description":"These lessons cover the theory of algorithmics you can read them in order as a course, or jump to any topic as a reference.","sidebar":"tutorialSidebar"},"mathematical-background/exercises":{"id":"mathematical-background/exercises","title":"Exercises: Mathematical Background","description":"These exercises practice the tools of the two lessons of the appendix the solutions are grouped at the end of the page.","sidebar":"tutorialSidebar"},"mathematical-background/induction-and-recurrences":{"id":"mathematical-background/induction-and-recurrences","title":"Induction, Correctness and Recurrences","description":"Recursive algorithms raise two questions: is the algorithm correct, and how long does it take? The answer to both uses the same idea. A recursive algorithm solves a problem by trusting that the smaller calls work; mathematical induction is the tool that makes that trust rigorous, and a recurrence is the equation that describes its cost in terms of the cost of the smaller calls.","sidebar":"tutorialSidebar"},"mathematical-background/references":{"id":"mathematical-background/references","title":"References: Mathematical Background","description":"Books, articles and resources to go deeper into the lessons of this appendix. The textbooks are listed in order of relevance to the course.","sidebar":"tutorialSidebar"},"mathematical-background/sums-and-logarithms":{"id":"mathematical-background/sums-and-logarithms","title":"Sums, Logarithms and Factorials","description":"Analyzing algorithms needs only a small amount of mathematics, but it needs it constantly. This lesson collects the facts used throughout the course, explains where each one comes from, and shows how to use them. It can be read on its own or consulted when a lesson refers to it.","sidebar":"tutorialSidebar"},"parallel-algorithms/exercises":{"id":"parallel-algorithms/exercises","title":"Exercises: Parallel Algorithms","description":"These exercises review the three lessons of the chapter the solutions are grouped at the end of the page.","sidebar":"tutorialSidebar"},"parallel-algorithms/fork-join-framework":{"id":"parallel-algorithms/fork-join-framework","title":"The Fork/Join Framework","description":"Creating and coordinating threads by hand is laborious and error-prone. Since Java 7, the package java.util.concurrent includes the Fork/Join framework, designed precisely to execute divide and conquer algorithms in parallel, using all the available processors automatically. This lesson explains how it works and how to use it, with the examples of the course repository.","sidebar":"tutorialSidebar"},"parallel-algorithms/parallel-algorithms":{"id":"parallel-algorithms/parallel-algorithms","title":"Concurrency and Parallelism","description":"Until now, every algorithm in this course has been sequential: one instruction after another, on a single processor. But the computers we use, from phones to servers, have several processor cores, and a sequential program uses only one of them. Parallel algorithms divide the work so that several cores can do it at the same time.","sidebar":"tutorialSidebar"},"parallel-algorithms/parallel-performance":{"id":"parallel-algorithms/parallel-performance","title":"Performance of Parallel Algorithms","description":"A parallel program is only worth its extra complexity if it is faster. But how much faster can it be? Does doubling the number of cores halve the time? This lesson presents the tools to answer these questions: how the complexity of an algorithm relates to its parallel execution time, how to measure the benefit of parallelism, and Amdahl\'s law, which sets a hard limit on it.","sidebar":"tutorialSidebar"},"parallel-algorithms/proofs":{"id":"parallel-algorithms/proofs","title":"Proofs: Parallel Algorithms","description":"This page derives the formulas of the performance lesson and proves that the Fork/Join scheme computes the same result as the sequential algorithm. Times are measured relative to the sequential time, which we take as 1 unless stated otherwise.","sidebar":"tutorialSidebar"},"parallel-algorithms/references":{"id":"parallel-algorithms/references","title":"References: Parallel Algorithms","description":"Books, articles and resources to go deeper into the lessons of this chapter. The textbooks are listed in order of relevance to the course.","sidebar":"tutorialSidebar"},"principles-of-algorithmics/algorithmic-thinking":{"id":"principles-of-algorithmics/algorithmic-thinking","title":"Algorithmic Thinking","description":"A programming language is only the vehicle we use to give instructions to a computer. What really decides whether a program is good is the method it follows to solve the problem. Algorithmics is the discipline that studies those methods: how to design them, how to be sure that they are correct, and how to predict how much time and memory they need.","sidebar":"tutorialSidebar"},"principles-of-algorithmics/asymptotic-notation":{"id":"principles-of-algorithmics/asymptotic-notation","title":"Asymptotic Notation","description":"In the previous lesson we obtained exact expressions such as $T(n) = 3n + 4$ and saw that the constants depend on arbitrary counting decisions and, in reality, on the machine. What does not depend on them is the rate of growth of the function: how fast $T(n)$ increases when $n$ becomes large.","sidebar":"tutorialSidebar"},"principles-of-algorithmics/case-study-pairwise":{"id":"principles-of-algorithmics/case-study-pairwise","title":"Case Study: Maximum Pairwise Product","description":"To truly understand why algorithmics matters, it helps to experience failure first. In this case study we take a deceptively simple problem and solve it again and again. Each version fixes a problem of the previous one, and each fix teaches a different lesson: about the limits of data types, the cost of naive strategies, the impact of data representation, and the danger of \\"optimizations\\" that are not actually correct.","sidebar":"tutorialSidebar"},"principles-of-algorithmics/complexity-analysis":{"id":"principles-of-algorithmics/complexity-analysis","title":"Complexity Analysis","description":"In the previous lesson we saw that measurements depend on the machine, the compiler and the implementation, and that comparing algorithms only by running them has serious limitations. We now develop the alternative: studying the algorithm on paper, by counting how many elementary operations it performs as a function of the size of its input.","sidebar":"tutorialSidebar"},"principles-of-algorithmics/complexity-of-loops":{"id":"principles-of-algorithmics/complexity-of-loops","title":"Complexity of Loops","description":"Most iterative algorithms are, at their core, combinations of loops. Once you can determine quickly and reliably how many times a loop runs, you can analyze almost any iterative program. This lesson collects the most common patterns, explains how to derive each result and points out the traps that appear most often in exams and in real code.","sidebar":"tutorialSidebar"},"principles-of-algorithmics/data-structures":{"id":"principles-of-algorithmics/data-structures","title":"Data Structures","description":"In the previous lessons we saw that the efficiency of a solution depends on the strategy we choose. It also depends, just as much, on how the data is organized in memory. The maximum pairwise product already gave us a hint: the same algorithm used several times more memory with a List than with an int[].","sidebar":"tutorialSidebar"},"principles-of-algorithmics/exercises":{"id":"principles-of-algorithmics/exercises","title":"Exercises: Principles of Algorithmics","description":"These exercises review the whole chapter, from the definition of an algorithm to searching. They are ordered by lesson, and within each group from easier to harder. Try each one before reading its solution: the solutions are grouped at the end of the page.","sidebar":"tutorialSidebar"},"principles-of-algorithmics/growth-rates":{"id":"principles-of-algorithmics/growth-rates","title":"Growth Rates and Predictions","description":"Asymptotic notation gives us a precise language. This lesson turns it into practical intuition: what the most common complexity classes mean in real time, how to predict the time an algorithm will need for a larger input, how to estimate the largest input it can handle in a given time, and why no improvement in hardware can change the complexity of an algorithm.","sidebar":"tutorialSidebar"},"principles-of-algorithmics/measuring-efficiency":{"id":"principles-of-algorithmics/measuring-efficiency","title":"Measuring Efficiency","description":"In the case study we compared four strategies for the maximum pairwise product and saw differences ranging from seconds to fractions of a millisecond. But how exactly should we compare algorithms? Is it enough to run them and look at the clock? What should we measure, and how can we trust the numbers?","sidebar":"tutorialSidebar"},"principles-of-algorithmics/proofs":{"id":"principles-of-algorithmics/proofs","title":"Proofs: Principles of Algorithmics","description":"This page collects the proofs behind the claims of the chapter. The lessons state the results and use them; here they are justified. Each section is self-contained, and the lessons link to the section they need. The proof techniques (induction and loop invariants) are explained in Induction, Correctness and Recurrences.","sidebar":"tutorialSidebar"},"principles-of-algorithmics/references":{"id":"principles-of-algorithmics/references","title":"References: Principles of Algorithmics","description":"Books, articles and resources to go deeper into the lessons of this chapter. The textbooks are listed in order of relevance to the course.","sidebar":"tutorialSidebar"},"principles-of-algorithmics/searching-case-studies":{"id":"principles-of-algorithmics/searching-case-studies","title":"Case Studies: Searching","description":"Searching is one of the most frequent operations in computing: looking up a user in a database, a word in a dictionary, a file in a directory, a value in a cache. In this final lesson of the chapter we apply everything we have learnt to three classic search algorithms. For each one we count instructions exactly, analyze the best, worst and average cases, express the result with asymptotic notation and connect it with real measurements.","sidebar":"tutorialSidebar"},"sorting/bubble-sort":{"id":"sorting/bubble-sort","title":"Bubble Sort","description":"Bubble sort is probably the best-known sorting algorithm, and also one of the least efficient. It is worth studying precisely because it is so simple: it lets us practise the exact analysis of comparisons and moves, introduces the important idea of inversions, and shows how small changes (a stop condition, a change of direction) affect the behavior without changing the complexity.","sidebar":"tutorialSidebar"},"sorting/comparing-sorting-algorithms":{"id":"sorting/comparing-sorting-algorithms","title":"Comparing Sorting Algorithms","description":"We have studied many sorting algorithms. This lesson brings them together: we compare their behavior with measurements, summarize their properties, give practical guidelines for choosing one, and introduce the sorting of data that does not fit in main memory.","sidebar":"tutorialSidebar"},"sorting/efficient-sorting":{"id":"sorting/efficient-sorting","title":"Beyond Quadratic Sorting","description":"Quicksort is not the only way to sort faster than $O(n^2)$. Each of the three basic ideas (exchange, insertion and selection) has an efficient counterpart, and there are also algorithms based on completely different principles. This lesson presents the most important ones, explains the theoretical limit that all comparison-based algorithms share, and shows how some algorithms manage to go below that limit.","sidebar":"tutorialSidebar"},"sorting/exercises":{"id":"sorting/exercises","title":"Exercises: Sorting","description":"These exercises review the whole sorting chapter. They use the versions of the algorithms given in the lessons (for example, the bubble sort of the lesson moves the smallest elements to the left, scanning from right to left). Try each exercise before reading its solution: the solutions are grouped at the end of the page.","sidebar":"tutorialSidebar"},"sorting/insertion-sort":{"id":"sorting/insertion-sort","title":"Insertion Sort","description":"Insertion sort is the method most people use, without thinking, to sort a hand of cards it performs fewer comparisons and moves, and it is extremely fast on data that is already almost sorted. For this reason, it is used inside many professional sorting algorithms.","sidebar":"tutorialSidebar"},"sorting/proofs":{"id":"sorting/proofs","title":"Proofs: Sorting","description":"This page proves the claims made in the sorting lessons: that each algorithm sorts correctly, the costs given in the lessons, and the limits that no comparison-based algorithm can break. The proofs use loop invariants and induction, explained in Induction, Correctness and Recurrences. Arrays are indexed from 0 and have $n$ elements.","sidebar":"tutorialSidebar"},"sorting/quicksort":{"id":"sorting/quicksort","title":"Quicksort","description":"Quicksort, invented by Tony Hoare around 1960, is one of the most important algorithms ever designed. It is the basis of the sorting routines of many programming languages and libraries, and it is usually the fastest general-purpose sorting algorithm in practice. It improves the idea of exchange: instead of exchanging adjacent elements, it exchanges elements that are far apart, removing many inversions at once.","sidebar":"tutorialSidebar"},"sorting/references":{"id":"sorting/references","title":"References: Sorting","description":"Books, articles and resources to go deeper into the lessons of this chapter. The textbooks are listed in order of relevance to the course.","sidebar":"tutorialSidebar"},"sorting/selection-sort":{"id":"sorting/selection-sort","title":"Selection Sort","description":"Selection sort follows the most direct strategy imaginable: find the smallest element and put it first; then find the smallest of the rest and put it second; and so on. It is the simple algorithm with the most predictable behavior, the one that performs the fewest exchanges, and, unlike the previous two, it is not stable.","sidebar":"tutorialSidebar"},"sorting/the-sorting-problem":{"id":"sorting/the-sorting-problem","title":"The Sorting Problem","description":"Sorting is one of the most frequent operations in any information system, and one of the most thoroughly studied problems in computer science. When there is a certain volume of data, keeping it sorted makes searching (and many other operations) much faster: we saw in the previous chapter that binary search needs about 20 steps to search a million sorted elements, while sequential search may need a million.","sidebar":"tutorialSidebar"}}}}')}}]);